@import url('https://fonts.googleapis.com/css2?family=Nunito+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* LEGO DNA — primary brick colors, chunky modular blocks, bold play energy */
.theme-lego-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.979 0 0);
  --surface-2: oklch(0.949 0 0);
  --fg: oklch(0.000 0 0);
  --fg-muted: oklch(0.471 0 0);
  --accent: oklch(0.543 0.216 28.3);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.523 0.142 248.5);
  --line: oklch(0.000 0 0);
  --success: oklch(0.537 0.162 146.4);
  --warning: oklch(0.871 0.178 91.8);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;
  --shadow-1: 0 3px 0 oklch(0 0 0 / 20%);
  --shadow-2: 0 6px 0 oklch(0 0 0 / 15%);
  --shadow-3: 0 12px 24px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 2px;
  --blur-amount: 0px;
  --font-display: "Nunito Sans", sans-serif;
  --font-body: "Nunito Sans", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.01em;
  --label-transform: none;
  --label-tracking: 0.05em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-lego-dna h1,
.theme-lego-dna h2,
.theme-lego-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-lego-dna { --font-ui: var(--font-display); }
.theme-lego-dna h1 { font-weight: 900; }
.theme-lego-dna button { border-bottom: 4px solid oklch(0 0 0 / 30%); font-weight: 800; }
.theme-lego-dna button:active { transform: translateY(2px); border-bottom-width: 2px; }

/* depth */
.theme-lego-dna { background-image: radial-gradient(circle at 8px 8px, oklch(0 0 0 / 4%) 0 5px, transparent 6px); background-size: 32px 32px; }
.theme-lego-dna thead th { background: var(--fg); color: oklch(1 0 0); font-weight: 800; text-transform: uppercase; letter-spacing: 0.08em; font-size: 0.72rem; }
.theme-lego-dna td { border-bottom: 1px solid oklch(0.9 0 0); }
.theme-lego-dna tbody tr:hover { background: oklch(0.949 0.04 92); }
.theme-lego-dna input, .theme-lego-dna select, .theme-lego-dna textarea { border: 2px solid var(--fg); border-radius: var(--radius-sm); background: oklch(1 0 0); font-weight: 600; }
.theme-lego-dna input:focus-visible, .theme-lego-dna select:focus-visible, .theme-lego-dna textarea:focus-visible { outline: 3px solid oklch(0.871 0.178 91.8); outline-offset: 1px; }
.theme-lego-dna a { color: var(--accent-2); font-weight: 800; text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 2px; }
.theme-lego-dna a:hover { color: var(--accent); }
.theme-lego-dna ::selection { background: oklch(0.871 0.178 91.8); color: oklch(0 0 0); }
.theme-lego-dna ::-webkit-scrollbar { width: 12px; }
.theme-lego-dna ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-lego-dna ::-webkit-scrollbar-thumb { background: var(--accent); border: 2px solid var(--fg); border-radius: 4px; }
.theme-lego-dna kbd { background: var(--accent); color: oklch(1 0 0); font-weight: 800; border-radius: 4px; border-bottom: 3px solid oklch(0.40 0.17 28.3); padding: 0.1em 0.45em; font-size: 0.72em; }
.theme-lego-dna .label-caps { font-weight: 800; }
.theme-lego-dna .themed-border { border-color: var(--fg); }
.theme-lego-dna button:hover { transform: translateY(-1px); }

/* alt mode: black baseplate — studs and brick colors glow in the dark */
.theme-lego-dna.alt-mode {
  --bg: oklch(0.145 0.000 0.0);
  --surface: oklch(0.195 0.000 0.0);
  --surface-2: oklch(0.240 0.000 0.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.72 0.01 90);
  --accent: oklch(0.600 0.216 28.3);
  --line: oklch(1 0 0 / 20%);
  --shadow-1: 0 3px 0 oklch(0 0 0 / 60%);
  --shadow-2: 0 6px 0 oklch(0 0 0 / 50%);
  --shadow-3: 0 12px 24px oklch(0 0 0 / 60%);
  background-image: radial-gradient(circle at 8px 8px, oklch(1 0 0 / 5%) 0 5px, transparent 6px);
  background-size: 32px 32px;
}
.theme-lego-dna.alt-mode thead th { background: oklch(0.871 0.178 91.8); color: oklch(0 0 0); }
.theme-lego-dna.alt-mode td { border-bottom-color: oklch(1 0 0 / 16%); }
.theme-lego-dna.alt-mode tbody tr:hover { background: oklch(0.24 0.03 92); }
.theme-lego-dna.alt-mode input, .theme-lego-dna.alt-mode select, .theme-lego-dna.alt-mode textarea { background: var(--surface); border-color: oklch(0.97 0.005 90); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
